begin;
do $$
#variable_conflict use_variable
declare aid uuid;other_id uuid;uid uuid;uid2 uuid;sid uuid;sid2 uuid;mid uuid;sl1 uuid;sl2 uuid;sl3 uuid;cfg jsonb;choices jsonb;o jsonb;oid uuid;rejected boolean;bid uuid;
begin
  insert into app_accounts(club_code,username,display_name,role,is_admin,must_change_password,membership_approved)values('gast','pay-admin-'||gen_random_uuid(),'Payment Admin','trainer',true,false,true)returning id into aid;
  insert into app_accounts(club_code,username,display_name,role,is_admin)values('svbb','pay-other-'||gen_random_uuid(),'Other Payment Admin','trainer',true)returning id into other_id;
  insert into app_accounts(club_code,username,display_name,role,must_change_password,membership_approved)values('gast','pay-member-'||gen_random_uuid(),'Payment Shooter','schutter',false,true)returning id into uid;
  insert into app_accounts(club_code,username,display_name,role,must_change_password,membership_approved)values('svbb','pay-member-'||gen_random_uuid(),'Second Payment Shooter','schutter',false,true)returning id into uid2;
  insert into platform_users(id,auth_provider_id)values(uid,'test:'||uid),(uid2,'test:'||uid2);
  insert into shooters(display_name,linked_user_id)values('Payment Shooter',uid)returning id into sid;
  insert into shooters(display_name,linked_user_id)values('Second Payment Shooter',uid2)returning id into sid2;
  insert into memberships(shooter_id,club_id)select sid,id from clubs where code='gast';
  insert into memberships(shooter_id,club_id)select sid2,id from clubs where code='svbb';
  insert into epp_payment_accounts(club_code,organization_id,organization_name,profile_id,credentials,can_receive)values('gast','org_paymenttest','Test recipient','pfl_paymenttest','encrypted-fixture',true);
  insert into epp_matches(club_id,organizer,match_date,match_dates,offered_disciplines)values('gast','Payment Integration Test','2036-05-28',array['2036-05-28'::date,'2036-05-29'::date],array['pistool','optiek'])returning id into mid;
  cfg:='{"first":"09:00","last":"10:00","duration":30,"changeover":0,"capacity":1,"gap":0,"opens":"2020-01-01T00:00","closes":"2036-05-27T23:00","published":true,"breaks":[],"overrides":[]}';
  perform epp_planner_configure(aid,mid,cfg,0);
  select id into sl1 from epp_match_slots where match_id=mid order by starts_at limit 1;
  select id into sl2 from epp_match_slots where match_id=mid order by starts_at offset 1 limit 1;
  select id into sl3 from epp_match_slots where match_id=mid order by starts_at offset 2 limit 1;
  choices:=jsonb_build_array(jsonb_build_object('discipline','pistool','slotId',sl1),jsonb_build_object('discipline','optiek','slotId',sl2));
  rejected:=false;begin perform epp_payment_configure(aid,mid,true);exception when others then if sqlerrm='betalingen_nog_niet_actief' then rejected:=true;else raise;end if;end;assert rejected,'global feature is disabled by default';
  update epp_payment_runtime set enabled=true;
  rejected:=false;begin perform epp_payment_configure(other_id,mid,true);exception when others then if sqlerrm='geen_beheerrechten' then rejected:=true;else raise;end if;end;assert rejected,'club ownership';
  perform epp_payment_configure(aid,mid,true);
  rejected:=false;begin perform epp_planner_book(uid,mid,sid,choices,0,'');exception when others then if sqlerrm='betaling_verplicht' then rejected:=true;else raise;end if;end;assert rejected,'old booking endpoint cannot bypass payment';
  o:=epp_payment_reserve(uid,mid,choices,0);oid:=(o->>'id')::uuid;
  assert o->>'amount_cents'='2400','two disciplines cost exactly EUR24';
  assert o->>'club_code'='gast' and o->>'organization_id'='org_paymenttest' and o->>'profile_id'='pfl_paymenttest','recipient frozen to organizer, not shooter club';
  assert epp_payment_reserve(uid,mid,choices,0)->>'id'=oid::text,'same attempt is reused';
  assert not exists(select 1 from epp_signups where match_id=mid),'no confirmed signup before payment';
  assert epp_payment_holds(sl1)=1 and epp_payment_holds(sl2)=1,'both slots held';
  update epp_payment_orders set expires_at=now()-interval '1 hour' where id=oid;
  assert epp_payment_holds(sl1)=1,'clock alone never releases an unverified payment';
  rejected:=false;begin perform epp_payment_reserve(uid2,mid,jsonb_build_array(jsonb_build_object('discipline','pistool','slotId',sl1)),0);exception when others then if sqlerrm='tijdslot_vol' then rejected:=true;else raise;end if;end;assert rejected,'holds prevent overselling';
  rejected:=false;begin perform epp_planner_configure(aid,mid,cfg||'{"first":"09:30"}',1);exception when others then if sqlerrm='tijdslot_betaling_loopt' then rejected:=true;else raise;end if;end;assert rejected,'cannot remove pending slot';
  perform epp_planner_set_slot_block(aid,mid,sl1,true,0);
  update epp_payment_orders set provider_id='tr_paymenttest' where id=oid;
  update epp_match_planners set closes_at=now()-interval '1 second' where match_id=mid;
  o:=epp_payment_apply(oid,'tr_paymenttest','paid',0);
  assert o->>'status'='paid','payment confirms even when admin blocked new bookings or closing time passed';
  assert (select count(*)=2 from epp_signup_disciplines d join epp_signups s on s.id=d.signup_id where s.match_id=mid),'exactly two confirmed disciplines';
  assert epp_payment_holds(sl1)=0,'hold replaced with booking';
  perform epp_payment_apply(oid,'tr_paymenttest','paid',0);
  assert (select planner_revision=1 from epp_signups where match_id=mid and shooter_id=sid),'duplicate webhook does not double confirm';
  perform epp_payment_apply(oid,'tr_paymenttest','paid',1200);
  assert (select refunded_cents=1200 from epp_payment_orders where id=oid),'refund status tracked';
  assert (select count(*)=2 from epp_signup_disciplines d join epp_signups s on s.id=d.signup_id where s.match_id=mid),'refund does not silently cancel registration';
  perform epp_planner_configure(aid,mid,cfg,1);
  perform epp_planner_book(uid,mid,sid,jsonb_build_array(jsonb_build_object('discipline','pistool','slotId',sl1),jsonb_build_object('discipline','optiek','slotId',sl3)),1,'');
  assert (select planner_revision=2 from epp_signups where match_id=mid and shooter_id=sid),'paid participants may move slot without paying twice';
  rejected:=false;begin perform epp_planner_book(uid,mid,sid,jsonb_build_array(jsonb_build_object('discipline','pistool','slotId',sl1)),2,'');exception when others then if sqlerrm='betaling_verplicht' then rejected:=true;else raise;end if;end;assert rejected,'partial discipline changes cannot bypass tariff';
  perform epp_planner_book(uid,mid,sid,'[]',2,'');
  assert (select registration_canceled from epp_payment_orders where id=oid),'canceled registrations never claim to be confirmed';
  perform epp_planner_set_slot_block(aid,mid,sl1,false,1);
  o:=epp_payment_reserve(uid2,mid,jsonb_build_array(jsonb_build_object('discipline','pistool','slotId',sl1)),0);oid:=(o->>'id')::uuid;
  assert o->>'amount_cents'='1200','one discipline costs exactly EUR12';
  update epp_payment_orders set provider_id='tr_expirytest' where id=oid;
  perform epp_payment_apply(oid,'tr_expirytest','expired',0);
  assert epp_payment_holds(sl1)=0,'verified expiry releases slot';
  assert not exists(select 1 from epp_signups where match_id=mid and shooter_id=sid2),'failed payment not confirmed';
  o:=epp_payment_reserve(uid2,mid,jsonb_build_array(jsonb_build_object('discipline','optiek','slotId',sl1)),0);oid:=(o->>'id')::uuid;
  assert o->>'amount_cents'='1200','Optics alone costs EUR12';
  update epp_payment_orders set provider_id='tr_reviewtest' where id=oid;
  update app_accounts set active=false where id=uid2;
  o:=epp_payment_apply(oid,'tr_reviewtest','paid',0);
  assert o->>'status'='review','received funds with a booking problem require manual review';
  assert epp_payment_holds(sl1)=1,'review holds remain safe';
  rejected:=false;begin perform epp_payment_retry_review(other_id,oid);exception when others then if sqlerrm='geen_beheerrechten' then rejected:=true;else raise;end if;end;assert rejected,'other club cannot retry a reviewed payment';
  update app_accounts set active=true where id=uid2;
  o:=epp_payment_retry_review(aid,oid);
  assert o->>'status'='paid','verified review can be resolved after fixing the booking problem';
  rejected:=false;begin perform epp_payment_configure(aid,mid,false);exception when others then if sqlerrm='betaalinstelling_vast' then rejected:=true;else raise;end if;end;assert rejected,'cannot silently disable payment after orders exist';
  assert not has_function_privilege('anon','epp_payment_apply(uuid,text,text,integer)','EXECUTE'),'anonymous cannot mark paid';
  assert not has_table_privilege('authenticated','epp_payment_accounts','SELECT'),'credentials hidden';
  assert not exists(select 1 from epp_payment_orders po where po.amount_cents<>1200*jsonb_array_length(po.choices)),'server tariff invariant';
end $$;
rollback;
